package bluray

import (
	"bufio"
	"math"
	"os"
	"strconv"
	"testing"
)

// TestMuslLibmVectors verifies the musl log/asinh/log1p ports against values
// computed by the actual system C library (the same libm .NET calls into).
// The vector file is generated by a small C program; skip when absent.
func TestMuslLibmVectors(t *testing.T) {
	const vectorsPath = "/tmp/opencode/libmtest/vectors.txt"
	file, err := os.Open(vectorsPath)
	if err != nil {
		t.Skipf("libm vectors not available: %v", err)
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 4096), 4096)
	checked := 0
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}
		var xb, lb, ab, pb uint64
		for i, field := range []*uint64{&xb, &lb, &ab, &pb} {
			v, err := strconv.ParseUint(line[i*17:i*17+16], 16, 64)
			if err != nil {
				t.Fatalf("bad vector line %q: %v", line, err)
			}
			*field = v
		}
		x := math.Float64frombits(xb)
		if got := math.Float64bits(muslLog(x)); got != lb {
			t.Fatalf("muslLog(%x): got %016X, want %016X", xb, got, lb)
		}
		if got := math.Float64bits(muslAsinh(x)); got != ab {
			t.Fatalf("muslAsinh(%x): got %016X, want %016X", xb, got, ab)
		}
		if got := math.Float64bits(muslLog1p(x)); got != pb {
			t.Fatalf("muslLog1p(%x): got %016X, want %016X", xb, got, pb)
		}
		checked++
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	t.Logf("verified %d vectors", checked)
}
